using UnityEngine;

namespace TruckSim.Audio
{
    /// <summary>
    /// Everything the player truck plays, as one asset. Generated by the editor importer
    /// (Game.Editor.Audio.VehicleAudioImporter) from tools/audio's manifest.json into
    /// Assets/_Project/Audio/Generated/Resources/VehicleAudio/ (gitignored, regenerated from the WAVs), and loaded at
    /// runtime with <see cref="LoadDefault"/>. Missing library = silent game with a warning, never an error.
    /// </summary>
    public sealed class VehicleAudioLibrary : ScriptableObject
    {
        /// <summary>Exterior reference clip and its prerendered cabin perspective (tools/audio sfx_layers.cab_filter).</summary>
        [System.Serializable]
        public struct PerspectivePair
        {
            public AudioClip ext, cab;
            public bool IsValid => ext != null;
        }

        public const string ResourcePath = "VehicleAudio/VehicleAudioLibrary";

        public EngineSoundBank exteriorEngine, cabEngine, exteriorEngineBrake, cabEngineBrake;
        public AudioClip turboWhistleLoop, turboLiftoff;
        public AudioClip airBrakeRelease, parkingBrakeSet, airDryerPurge, gearshiftAir;
        public AudioClip roadRollLoop, windLoop, gearWhineLoop;
        [Header("Cabin perspective of the original layers")]
        public AudioClip airBrakeReleaseCab, parkingBrakeSetCab, airDryerPurgeCab, gearshiftAirCab, roadRollLoopCab, windLoopCab;

        [Header("Audio-layers pass (docs/AUDIO_DESIGN.md section 4)")]
        public AudioClip parkingBrakeRelease, parkingBrakeReleaseCab, airDryerPurgeB, airDryerPurgeBCab;
        [Tooltip("Tyre rolling loops indexed by SurfaceKind (0 dry asphalt = road roll, 1 wet, 2 concrete, 3 cobbles, 4 gravel, 5 grass).")]
        public PerspectivePair[] tyreSurface = new PerspectivePair[6];
        public PerspectivePair tyreSqueal, retarder, compressor, ambientBed, forklift, crowCaw, indicatorTick, indicatorTock;
        public AudioClip birdSparrow, birdTit;
        [Tooltip("ADR 0145: tyre scrub in tight slow turns (procedural placeholder, tools/audio/sfx_layers.tyre_scrub_loop).")]
        public PerspectivePair tyreScrub;

        [Header("ElevenLabs layers (ADR 0137; game/Assets/_Project/Audio/ElevenLabs/el_manifest.json)")]
        public EngineSoundBank elExteriorEngine, elCabEngine, elExteriorEngineBrake, elCabEngineBrake;
        public PerspectivePair elEngineStart, elEngineStop, elIdleClatter, elRetarder, elTurboWastegate;

        [Header("ElevenLabs effects (ADR 0142; el_manifest.json group \"fx\", tools/audio/el_fx.py)")]
        [Tooltip("Pneumatics / gearbox one-shots (exterior + prerendered cabin, or one clip for both).")]
        public PerspectivePair elAirBrakeRelease, elParkingBrakeSet, elParkingBrakeRelease, elAirDryerPurge, elAirDryerPurgeB,
            elGearshiftUp, elGearshiftDown, elTrailerCouple, elSuspBump, elIndicatorTick, elIndicatorTock, elCabSwitch,
            elDoorOpen, elDoorClose;
        [Tooltip("Loops. Cabin-only recordings (dry tyres, wind, gear whine) have ext = null: the exterior keeps the procedural clip.")]
        public PerspectivePair elCompressor, elHorn, elReverseBeeper, elAmbientBed, elTurboWhine, elTurboRush;
        public AudioClip elTyreDryCab, elWindCab, elGearWhineCab;
        [Tooltip("Tyre loops by SurfaceKind; invalid entries keep the procedural loop (cobbles, grass; dry = elTyreDryCab).")]
        public PerspectivePair[] elTyreSurface = new PerspectivePair[6];

        [Header("ElevenLabs REGEN-03 (ADR 0145; el_fx.py REGEN03_SLOTS, takes picked by el_regen03.py)")]
        [Tooltip("Tyre scrub (tight slow turn) and hard squeal, exterior + cabin recordings. Used in both sound sets when imported.")]
        public PerspectivePair elTyreScrub, elTyreSqueal;

        /// <summary>The ElevenLabs effect set is imported (ADR 0142).</summary>
        public bool HasElevenLabsFx => elAirBrakeRelease.IsValid;

        /// <summary>The ElevenLabs engine set is imported (both perspectives of the rpm x load grid).</summary>
        public bool HasElevenLabs => elExteriorEngine != null && elCabEngine != null;

        [Tooltip("manifest.json generator line and clip count, for the log.")]
        public string sourceInfo;

        public static VehicleAudioLibrary LoadDefault() => Resources.Load<VehicleAudioLibrary>(ResourcePath);
    }
}
